#include "opensim/scene/inventory_script_rez.hpp"
#include <iostream>
#include <bit>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto tail=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-tail.size(),'0')+tail);}
std::string task(const InventoryScriptTask& t){auto& i=t.item;return i.item.str()+":"+i.asset.str()+":"+i.owner.str()+":"+i.creator.str()+":"+i.last_owner.str()+":"+i.group.str()+":"+std::to_string(i.base_permissions)+":"+std::to_string(i.current_permissions)+":"+std::to_string(i.everyone_permissions)+":"+std::to_string(i.group_permissions)+":"+std::to_string(i.next_permissions)+":"+std::to_string(i.flags)+":"+std::to_string(i.creation_date)+":"+std::to_string(i.type)+":"+std::to_string(i.inventory_type)+":"+i.name+":"+i.description+":"+t.parent.str()+":"+t.parent_part.str()+":"+(t.running?"1":"0");}
std::string probe(int kind,int mode,int failure){std::string trace;auto step=[&](int p,std::string s){trace+="|"+s;if(failure==p)throw std::runtime_error("injected");};services::InventoryItem source;source.id=id(2);source.asset_id=id(4);source.owner=id(7);source.creator_id=(mode&2048)?id(5).str()+";profile;name":id(5).str();source.name="Script";source.description="Description";source.asset_type=(mode&256)?7:10;source.inventory_type=(mode&256)?7:10;source.base_permissions=0x9e000;source.current_permissions=(mode&1024)?0x86000:0x8e000;source.everyone_permissions=0x8a000;source.group_permissions=0x84000;source.next_permissions=0x82000;source.flags=std::bit_cast<std::int32_t>((mode&512)?0x80004000u:0x4000u);source.creation_date=999;source.group_id=id(8);
 InventoryScriptPart part{id(6),(mode&128)?id(9):id(1)};InventoryScriptRezBackend b;b.default_engine="YEngine";
 b.random_uuid=[&]{step(1,"NEW");return id(3);};b.inventory_item=[&](auto a,auto i)->std::optional<services::InventoryItem>{step(2,"GET:"+a.str()+":"+i.str());if(mode&1)return {};return source;};if(!(mode&2))b.library_item=[&](auto i)->std::optional<services::InventoryItem>{step(3,"LIB:"+i.str());if(mode&4)return {};return source;};
 b.scene_part=[&](auto local)->std::optional<InventoryScriptPart>{step(4,"PART:"+std::to_string(local));if(mode&8)return {};return part;};b.can_edit_inventory=[&](auto p,auto a){step(5,"EDIT:"+p.str()+":"+a.str());return !(mode&16);};b.group_part=[&](auto,auto local)->std::optional<InventoryScriptPart>{step(6,"GROUP:"+std::to_string(local));if(mode&32)return {};return part;};b.unix_time=[&]{step(7,"TIME");return 111u;};b.propagate_permissions=[&]{step(8,"PROPAGATE");return bool(mode&64);};b.root_flags=[&](auto){step(9,"FLAGS");return (mode&512)?0x10000u:0u;};
 b.insert_task=[&](auto p,auto value,bool allowed){step(10,"INSERT:"+p.id.str()+":"+(allowed?"1:":"0:")+task(*value));};b.invalidate_deep_permissions=[&](auto){step(11,"INVALIDATE");};b.compile=[&](auto p,auto item,int start,bool post,const auto& engine,int state){step(12,"COMPILE:"+p.id.str()+":"+item.str()+":"+std::to_string(start)+":"+(post?"1":"0")+":"+engine+":"+std::to_string(state));};b.new_script=[&](auto a,auto p,auto i){step(13,"EVENT:"+a.str()+":"+p.id.str()+":"+i.str());};b.resume=[&](auto){step(14,"RESUME");};b.properties=[&](auto p,auto a){step(15,"PROPS:"+p.id.str()+":"+a.str());};b.rez_new=[&](auto a,const auto& row)->std::optional<InventoryScriptPart>{step(16,"REZNEW:"+a.str()+":"+row.id.str());if(mode&8)return {};return part;};b.log=[&](auto){step(17,"LOG");};
 InventoryScriptRezController controller(std::move(b));std::string status="OK";try{if(kind==0){auto wire=source;if(mode&4096)wire.id={};controller.rez(id(1),wire,id(10),123);}else if(kind==1)status=controller.rez_existing(id(1),id(2),123)?"YES":"NO";else status=controller.add_to_group(id(1),part,123,source,(mode&1024)?framework::Uuid{}:id(3),!(mode&256))?"YES":"NO";}catch(...){status="THROW";}return status+trace;
}
}
int main(int argc,char**argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int k,m,f;while(std::cin>>k>>m>>f)std::cout<<probe(k,m,f)<<'\n';return 0;}int count=0;auto check=[&](bool v,const char*s){++count;if(!v)throw std::runtime_error(s);};check(probe(0,0,0).starts_with("OK|NEW|GET:"),"copyUUID beforefetch");check(probe(1,1|2,0).find("|PART:")==std::string::npos,"missinglibrary skipspart");check(probe(1,32,0).find("|LOG|COMPILE:")!=std::string::npos,"failed groupadd stillcompiles");check(probe(2,128|64|256|512,0).find("|PROPAGATE|FLAGS|INSERT:")!=std::string::npos,"propagation beforeallowedDrop");check(probe(2,0,0).find("PROPAGATE")==std::string::npos,"owner bypassespropagation query");check(probe(0,4096,0).find("|REZNEW:")!=std::string::npos,"newscript delegated");std::cout<<"PASS: "<<count<<" inventory script rez checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
